output_text:
[
  {
    "id": "h1_must_take_entrance_cart",
    "text": "A shopper is obliged to take the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "h2_pick_items_only_with_cart",
    "text": "Items may only be picked up while the shopper is pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "h3_no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than transporting it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_item_into_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "pushing_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "take_item_into_hand"
        ]
      }
    }
  },
  {
    "id": "h4_must_return_cart_to_bay",
    "text": "Before leaving the store, the shopper is obliged to return the cart to the front-left cart bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "leave_cart_in_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "leave_cart_in_return_bay"
    }
  },
  {
    "id": "h5_only_drop_cart_at_bay",
    "text": "A cart may be put down only in the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "drop_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "drop_cart_outside_bay"
    }
  },
  {
    "id": "h6_no_cart_exit",
    "text": "The shopper is prohibited from exiting the supermarket while still possessing a cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        },
        "exit_on_foot": {
          "pre": {
            "and": [
              "exit_cell",
              {
                "not": "pushing_cart"
              },
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "h7_no_carts_in_exit_zone",
    "text": "Shopping carts are forbidden in the eastern exit-side walking zone.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_side_zone": {
          "or": [
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_exit_side_zone": {
          "and": [
            "pushing_cart",
            "exit_side_zone"
          ]
        }
      },
      "events": {
        "enter_exit_side_zone_with_cart": {
          "pre": {
            "and": [
              "pushing_cart",
              "MOVE"
            ]
          },
          "post": "exit_side_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_exit_side_zone",
          "enter_exit_side_zone_with_cart"
        ]
      }
    }
  },
  {
    "id": "h8_no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the bay, shopping interactions with shelves are prohibited.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": "cartAt(0,1)",
        "not_pushing_cart": {
          "not": "hasCart"
        },
        "post_return_phase": {
          "and": [
            "cart_returned_to_bay",
            "not_pushing_cart"
          ]
        }
      },
      "events": {
        "post_return_item_pickup": {
          "pre": {
            "and": [
              "post_return_phase",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_item_pickup"
    }
  }
]
